class CommonMethods(object):
    """Define common methods for use in all tests below."""

    def dict_check(self, dict1, dict2):
        """Check the equality of two dicts.

        Args:
            dict1 (dict): First dictionary to be compared
            dict2 (dict): Second dictionary to be compared

        Raises:
            AssertionError: If dictionaries are not equal.
        """
        # zip() and zip_longest() produce tuples for the items
        # identified, where in the case of a dict, the first item
        # in the tuple is the key and the second item is the value;
        # in the case where the dicts are not of identical size,
        # zip_longest() will use the fill value created below as a
        # substitute in the dict that has missing content; this
        # value is given as a tuple to be of comparable structure
        # to the normal output from zip_longest()
        fill_val = ('substituted entry', 5.2)

        # In this structure, k and k2 are the keys that correspond to
        # the dicts or unitary values that are found in i and i2,
        # respectively, at the current level of the recursive
        # exploration of dict1 and dict2, respectively
        for (k, i), (k2, i2) in itertools.zip_longest(sorted(dict1.items()),
                                                      sorted(dict2.items()),
                                                      fillvalue=fill_val):

            # Confirm that at the current location in the dict structure,
            # the keys are equal; this should fail if one of the dicts
            # is empty, is missing section(s), or has different key names
            self.assertEqual(k, k2)

            # If the recursion has not yet reached the terminal/leaf node
            if isinstance(i, dict):
                # Test that the dicts from the current keys are equal
                self.assertCountEqual(i, i2)
                # Continue to recursively traverse the dict
                self.dict_check(i, i2)
            # At the terminal/leaf node, formatted as a numpy array or list
            # (for time sensitive valuation test cases)
            elif isinstance(i, numpy.ndarray) or isinstance(i, list):
                self.assertTrue(type(i) is type(i2) and len(i) == len(i2))
                for x in range(0, len(i)):
                    # Handle lists of strings
                    if isinstance(i[x], str):
                        self.assertEqual(i[x], i2[x])
                    # Ensure that very small numbers do not reduce to 0
                    elif round(i[x], 5) != 0:
                        self.assertAlmostEqual(i[x], i2[x], places=5)
                    else:
                        self.assertAlmostEqual(i[x], i2[x], places=10)
            elif isinstance(i, str):
                self.assertEqual(i, i2)
            # At the terminal/leaf node, formatted as a point value
            else:
                # Compare the values, allowing for floating point inaccuracy.
                # Ensure that very small numbers do not reduce to 0
                if round(i, 1) != 0:
                    self.assertAlmostEqual(i, i2, places=2)
                else:
                    self.assertAlmostEqual(i, i2, places=10)


class UserOptions(object):
    """Generate sample user-specified execution options."""
    def __init__(self, site_energy, capt_energy, regions, tsv_metrics,
                 sect_shapes, rp_persist, health_costs, split_fuel,
                 no_scnd_lgt, floor_start, pkg_env_costs, exog_hp_rates,
                 grid_decarb, adopt_scn_restrict, retro_set, add_typ_eff,
                 pkg_env_sep, alt_ref_carb, detail_brkout, fugitive_emissions,
                 warnings, no_eff_capt, no_lnkd_stk, no_lnkd_op, elec_upgrade_costs,
                 low_volume_rate, state_appl_regs, bps, codes, incentive_levels,
                 incentive_restrictions):
        # Options include site energy outputs, captured energy site-source
        # calculation method, alternate regions, time sensitive output metrics,
        # sector-level load shapes, and verbose mode that prints all warnings
        self.site_energy = site_energy
        self.captured_energy = capt_energy
        self.alt_regions = regions
        self.rp_persist = rp_persist
        self.verbose = warnings
        self.tsv_metrics = tsv_metrics
        self.health_costs = health_costs
        self.sect_shapes = sect_shapes
        self.split_fuel = split_fuel
        self.no_scnd_lgt = no_scnd_lgt
        self.floor_start = floor_start
        self.pkg_env_costs = pkg_env_costs
        self.exog_hp_rates = exog_hp_rates
        self.grid_decarb = grid_decarb
        self.adopt_scn_restrict = adopt_scn_restrict
        self.retro_set = retro_set
        self.add_typ_eff = add_typ_eff
        self.pkg_env_sep = pkg_env_sep
        self.alt_ref_carb = alt_ref_carb
        self.detail_brkout = detail_brkout
        self.fugitive_emissions = fugitive_emissions
        self.no_eff_capt = no_eff_capt
        self.no_lnkd_stk_costs = no_lnkd_stk
        self.no_lnkd_op_costs = no_lnkd_op
        self.elec_upgrade_costs = elec_upgrade_costs
        self.low_volume_rate = low_volume_rate
        self.state_appl_regs = state_appl_regs
        self.bps = bps
        self.codes = codes
        self.incentive_levels = incentive_levels
        self.incentive_restrictions = incentive_restrictions


class NullOpts(object):
    """Generate null set of user-specified execution options.

    Attributes:
        opts (object): Sample null user options.
        opts_dict (dict): Dict-formatted sample null user options.
    """

    def __init__(self):
        # Note: technically, the 'detail_brkout' opt should be set to
        # False for this null case; however, because tests in this suite
        # were previously developed using the most detailed regional
        # breakouts, the option is set to continue using those breakouts
        # for regions only
        test_ecms = Path(__file__).parent / "test_files" / "ecm_definitions"
        self.opts = ecm_args(["--ecm_directory", str(test_ecms),
                              "--detail_brkout", "regions", "--alt_regions", "AIA",
                              "--no_eff_capt", "--no_lnkd_stk_costs", "in_adopt_and_report",
                              "--elec_upgrade_costs", "ignore"])
        self.opts_dict = vars(self.opts)


class MarketUpdatesTest(unittest.TestCase, CommonMethods):
    """Test 'fill_mkts' function.

    Ensure that the function properly fills in market microsegment data
    for a series of sample measures.

    Attributes:
        opts (object): Stores user-specified execution options for tests using
            default AIA regions.
        opts_site_energy (object): Stores user-specified execution options for
            tests of measures assessed under the site energy use setting.
        opts_emm (object): Stores user-specified execution options for tests
            using EMM regions.
        opts_state (object): Stores user-specified execution options for tests
            using state regions.
        opts_hp_rates (object): Stores user-specified execution options for
            tests of heat pump measures w/ exogenous conversion rates.
        opts_hp_norates (object): Stores user-specified execution options for
            tests of heat pump measures w/o exogenous conversion rates.
        opts_fmeth (object): Stores user-specified execution options for
            tests of fugitive methane emissions.
        opts_frefr (object): Stores user-specified execution options for
            tests of fugitive refrigerant emissions.
        convert_data (dict): ECM cost conversion data.
        tsv_data (dict): Data needed for time-sensitive efficiency valuation.
        sample_mseg_in (dict): Sample baseline microsegment stock/energy,
            default AIA regions.
        sample_mseg_in_emm (dict): Sample baseline microsegment stock/energy,
            EMM regions.
        sample_cpl_in (dict): Sample baseline technology cost, performance,
            and lifetime, default AIA regions.
        sample_cpl_in_emm (dict): Sample baseline technology cost, performance,
            and lifetime, EMM regions.
        ok_tpmeas_fullchk_in (list): Valid sample measure information
            to update with markets data; measure cost, performance, and life
            attributes are given as point estimates. Used to check the full
            measure 'markets' attribute under a 'Technical potential scenario.
        ok_tpmeas_partchk_in (list): Valid sample measure information to update
            with markets data under default AIA region analysis; measure cost,
            performance, and lifetime attributes are given as point estimates.
            Used to check the 'master_mseg' branch of measure 'markets'
            attribute under a 'Technical potential scenario.
        ok_tpmeas_partchk_emm_in (list): Valid sample measure information to
            update with markets data under EMM region analysis.
        ok_tpmeas_partchk_state_in (list): Valid sample measure information to
            update with markets data under state region analysis, regional cost adjustment off.
        ok_tpmeas_partchk_state_regadj_in (list): Valid sample measure information to
            update with markets data under state region analysis, regional cost adjustment on.
        ok_mapmeas_partchk_in (list): Valid sample measure information
            to update with markets data; measure cost, performance, and life
            attributes are given as point estimates. Used to check the
            'master_mseg' branch of measure 'markets' attribute under a 'Max
            adoption potential scenario.
        ok_tpmeas_sitechk_in (list): Valid sample measure information to
            update with markets data, where energy data are in site units.
        ok_distmeas_in (list): Valid sample measure information to
            update with markets data; measure cost, performance, and lifetime
            attributes are given as probability distributions.
        ok_partialmeas_in (list): Partially valid measure information to update
            with markets data.
        failmeas_in (list): Invalid sample measure information that should
            yield error when entered into function.
        warnmeas_in (list): Incomplete sample measure information that
            should yield warnings when entered into function (measure
            sub-market scaling fraction source attributions are invalid).
        ok_mapmeas_hp_chk_in (list): Valid sample measure information to update
            with markets data, where measures pertain to heat pump tech and only the
            heating stock costs of comparable baseline equipment are counted.
        ok_coolcost_chk_in (list): Valid sample measure information to update
            with markets data, where measures pertain to heat pump tech. and both heating
            and cooling costs of comparable baseline equipment are counted.
        ok_tp_fmeth_chk_in (list): Valid sample measure information to update
            with markets data, where measures affect fugitive methane.
        ok_map_frefr_chk_in (list): Valid sample measure information to update
            with markets data, where measures affect fugitive refrigerants.
        ok_tpmeas_fullchk_msegout (list): Master market microsegments
            information that should be yielded given 'ok_tpmeas_fullchk_in'.
        ok_tpmeas_fullchk_competechoiceout (list): Consumer choice information
            that should be yielded given 'ok_tpmeas_fullchk_in'.
        ok_tpmeas_fullchk_msegadjout (list): Secondary microsegment adjustment
            information that should be yielded given 'ok_tpmeas_fullchk_in'.
        ok_tpmeas_fullchk_break_out (list): Output breakout information that
            should be yielded given 'ok_tpmeas_fullchk_in'.
        ok_tpmeas_partchk_msegout (list): Master market microsegments
            information that should be yielded given 'ok_tpmeas_partchk_in'.
        ok_tpmeas_partchk_msegout_emm (list): Master market microsegments
            information that should be yielded via 'ok_tpmeas_partchk_emm_in'.
        ok_tpmeas_partchk_msegout_state (list): Master market microsegments
            information that should be yielded via 'ok_tpmeas_partchk_state_in'.
        ok_tpmeas_partchk_msegout_state_regadj (list): Master market microsegments
            information that should be yielded via 'ok_tpmeas_partchk_state_regadj_in'.
        ok_mapmeas_partchck_msegout (list): Master market microsegments
            information that should be yielded given 'ok_mapmeas_partchk_in'.
        ok_distmeas_out (list): Means and sampling Ns for measure energy/cost
            markets and lifetime that should be yielded given 'ok_distmeas_in'.
        ok_partialmeas_out (list): Master market microsegments information
            that should be yielded given 'ok_partialmeas_in'.
        ok_warnmeas_out (list): Warning messages that should be yielded
            given 'warnmeas_in'.
        ok_hpmeas_rates_mkts_out (list): Master market microsegments info.
            that should be yielded given 'ok_mapmeas_hp_chk_in'.
        ok_hpmeas_rates_breakouts (list): Outputs breakouts info. (with fuel
            splits) that should be yielded given a subset of the measures
            included in 'ok_mapmeas_hp_chk_in'.
        ok_tp_fmeth_mkts_out (list): Master market microsegments info.
            that should be yielded for fugitive methane measure tests.
        ok_map_frefr_mkts_out (list): Master market microsegments info.
            that should be yielded fugitive refrigerant measure tests.
    """

